insert into public.site_settings (id, name, short_name, diocese, location, address, phone, phone_display, whatsapp_number, email, daily_mass_time, office_hours, founded_on, mission, vision, philosophy, core_values, map_embed_url, map_link_url) values
  (1, 'Watakatifu Wote Senta (All Saints Conference Centre)', 'Watakatifu Wote Senta', 'Catholic Diocese of Ngong', 'Ngong, Kahara Road, Kenya', 'Kahara Road, Ngong, Kajiado County, Kenya', '+254704346417', '+254 704 346 417', '254704346417', 'wws@ngongdiocese.org', '7:00 AM', 'Mon–Sat, 8:00 AM – 5:00 PM', '1986-11-01', 'Transforming lives through evangelization, pastoral care and social-economic development.', 'A loving community of God living fulfilled lives.', 'We believe in the sanctity of life and care for planet (Mother Earth). We are driven by a conviction that service to mankind is service to God.', '[{"title":"Integrity","description":"We are guided, and live by Christian values at all times and in all circumstances."},{"title":"Unity","description":"We are committed to unity of purpose and mind; we submit to each other and to God."},{"title":"Equity","description":"We believe everyone deserves a dignified life, and fair access to justice and opportunities."},{"title":"Professionalism","description":"We strive for excellence in all we do, and achieve this by investing in innovation, creativity, reflection and perpetual improvement."},{"title":"Integrity of Creation","description":"In all our actions, we strive to protect the environment: we strive for an optimal balance between human and environmental well-being."}]'::jsonb, 'https://www.google.com/maps?q=Kahara+Road,+Ngong,+Kenya&output=embed', 'https://www.google.com/maps/search/?api=1&query=Kahara+Road+Ngong+Kenya');
insert into public.facilities (slug, name, capacity_min, capacity_max, price_kes, price_note, description, features, seating_styles, image_url, sort_order, is_published) values
  ('st-bakhita', 'St. Bakhita Conference Hall', 8, 10, 4000, 'Standard day rate (KES 4,000)', 'A quiet, well-lit executive meeting space ideal for governance committees, small planning teams, and private strategy sessions.', array['High-speed Wi-Fi', 'Shared Projector access', 'Water dispenser with fresh refills', 'Executive conference seating', 'Natural daylight and serene garden view', 'Direct veranda access for tea breaks']::text[], array['Classroom', 'Boardroom']::text[], 'https://images.unsplash.com/photo-1462826303086-329426d1aef5?auto=format&fit=crop&w=1200&q=80', 0, true),
  ('st-julian', 'St. Julian Conference Hall', 40, 55, 8000, 'Standard day rate (KES 8,000)', 'A medium-capacity conference facility suited for diocesan seminars, parish councils, NGO workshops, and corporate training retreats.', array['High-speed Wi-Fi', 'Screen and Projector provision', 'Audio amplification compatibility', 'Water dispenser stationed inside', 'Flexible table and chair arrangements (155 chairs available on campus)', 'Spacious acoustic dampening layout']::text[], array['Classroom', 'Boardroom']::text[], 'https://images.unsplash.com/photo-1431540015161-0bf868a2d407?auto=format&fit=crop&w=1200&q=80', 1, true),
  ('st-bernard', 'St. Bernard Main Hall', 55, 100, 15000, 'KES 15,000 PA inclusive (Full Sound System Included)', 'Our flagship conference and plenary hall designed for large assemblies, annual general meetings, deanery gatherings, and major spiritual seminars.', array['Dedicated PA Sound System (inclusive in hall rate)', 'High-definition Projector & motorized screen setup', 'High-speed Wi-Fi', 'Dual water dispensers', 'Full podium with microphone points', 'Ample natural ventilation and double doors leading to central grounds']::text[], array['Classroom', 'Boardroom']::text[], 'https://images.unsplash.com/photo-1604328698804-8d5a31499ca6?auto=format&fit=crop&w=1200&q=80', 2, true);
insert into public.accommodation_options (slug, name, category, capacity_desc, rooms_count, price_estimate, description, amenities, image_url, is_available, sort_order) values
  ('main-centre', 'Centre Main Residential Wings', 'Group & Retreat Dormitory / En-Suite Rooms', 'Historically up to 62 beds total campus capacity', 28, 'Rates provided upon inquiry based on group size & duration', 'Peaceful, simple residential quarters designed for spiritual retreatants, priests, religious communities, and conference participants seeking serene overnight stays in Ngong.', array['Clean bedding & mosquito net provisions', 'Shared or private bathrooms with hot water showers', 'Quiet desk and reading lamp for personal reflection', 'Close proximity to the Daily Mass Chapel', 'Direct access to landscaped walking paths and prayer gardens']::text[], 'https://lzphdqkpswzhxlwqwxbp.supabase.co/storage/v1/object/public/media/accommodation/bedroom-2.webp', true, 0),
  ('guest-house', 'All Saints Guest House Apartments', 'Self-Contained Executive Apartments', 'Six (6) self-contained private apartments', 6, 'Special executive and visiting clergy rates (Inquire for quotes)', 'Six independent, self-contained residential units providing greater privacy for visiting resource facilitators, senior clergy, retreat directors, or small families.', array['Self-contained private bathroom & water heating', 'Sitting lounge and work desk', 'Quiet veranda overlooking the Ngong landscape', 'Tea & coffee kettle station', 'Daily housekeeping and linen services']::text[], 'https://lzphdqkpswzhxlwqwxbp.supabase.co/storage/v1/object/public/media/accommodation/apartment-sitting-room.webp', true, 1),
  ('clergy-suite', 'Visiting Priests & Facilitators Quarters', 'Dedicated Clergy & Director En-Suite', 'Individual self-contained rooms', null, 'Pastoral & institutional concessions applicable upon inquiry', 'Dedicated quiet en-suite rooms reserved for priests celebrating Daily Mass, retreat conductors, spiritual directors, and visiting ecclesiastical dignitaries.', array['Private study desk with spiritual reading library', 'Private en-suite bathroom', 'Immediate covered walkway access to the Sacristy and Chapel', 'Peaceful, uninterrupted prayer atmosphere']::text[], 'https://lzphdqkpswzhxlwqwxbp.supabase.co/storage/v1/object/public/media/accommodation/bedroom-1.webp', true, 2);
insert into public.catering_services (slug, title, description, ideal_for, includes, image_url, sort_order) values
  ('conf', 'Conference Catering & Tea Breaks', 'Wholesome morning and afternoon refreshments with traditional Kenyan tea, freshly brewed coffee, snacks, and balanced buffet lunches for conference participants.', 'Workshops, strategic retreats, seminars & AGMs', array['Morning herbal & black tea with savory Kenyan bites (mandazi, samosas, sweet potatoes)', 'Full balanced buffet lunch with meat, vegetarian options, fresh greens, and seasonal fruits', 'Afternoon refreshment break with hot drinks and confectioneries', 'Continuous fresh drinking water support throughout proceedings']::text[], 'https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&w=1200&q=80', 0),
  ('retreat', 'Retreatant & Spiritual Fasting Hospitality', 'Nourishing, mindful meals thoughtfully timed around liturgies, prayers, and silent periods. Customized fasting or vegetarian provisions prepared upon advance notice.', 'Silent retreats, discernment weekends, parish prayer groups', array['Early morning post-Mass breakfast', 'Wholesome, home-style lunch and dinner menus', 'Dietary considerations accommodated (diabetic, low-sodium, vegetarian)', 'Peaceful dining hall ambiance encouraging quiet reflection']::text[], 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=1200&q=80', 1),
  ('events', 'Event & Parish Feast Celebrations', 'Comprehensive catering for large Catholic milestone celebrations, ordinations anniversaries, feast day banquets, and family gatherings on our spacious grounds.', 'All Saints Day feast, deanery jubilees, parish thanksgiving', array['Generous celebration buffet spreads', 'Professional serving staff and warm table hospitality', 'Setup coordination on lawn grounds or main banquet hall', 'Beverage and dessert service coordination']::text[], 'https://images.unsplash.com/photo-1519671482749-fd09be7ccebf?auto=format&fit=crop&w=1200&q=80', 2),
  ('private', 'Private Group & Committee Dining', 'Intimate dining arrangements for executive leadership teams, diocesan consultors, and boards requiring discreet discussion over a meal.', 'Executive committees, Diocesan boards, visiting delegations', array['Tailored course service in the private dining lounge', 'Dedicated host staff during dining hours', 'Custom beverage service and fresh local fruit juices']::text[], 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=80', 3);
insert into public.laundry_services (title, description, turnaround_time, notes, is_available, sort_order) values
  ('Guest laundry', 'A well-equipped laundry is available to guests staying at the centre.', 'Arranged with the office', '', true, 0);
insert into public.mass_schedules (day_label, time_label, celebration_type, description, location, is_special, sort_order) values
  ('Monday through Sunday (Every Day)', '7:00 AM', 'Daily Morning Mass', 'The Holy Sacrifice of the Mass celebrated daily in the peace of the morning. All resident retreatants, visiting conference groups, and local faithful are warmly welcome.', 'Watakatifu Wote Senta Main Chapel', false, 0),
  ('1 November (Annual Solemnity)', '10:00 AM', 'Diocesan Solemnity & Patronal Celebration', 'Patronal Feast of All Saints — celebrating the anniversary of the opening of Watakatifu Wote Senta (1 Nov 1986) with the Bishop, clergy, and diocesan community.', 'Open-Air Grounds / St. Bernard Main Hall', true, 1);
insert into public.retreats (slug, title, category, target_audience, description, start_date, end_date, duration, requirements, fee_kes, fee_note, image_url, sort_order, is_published) values
  ('silent', 'Weekend of Silent Discernment & Contemplation', 'individual', 'Laity, religious, and seekers desiring quiet time with God', 'Step away from the busyness of everyday life into the serene silence of the Ngong Hills. Features daily Eucharistic adoration, private spiritual direction, and quiet prayer walks.', '2026-10-09', '2026-10-11', '3 Days (Friday 4:00 PM – Sunday 2:00 PM)', array['Bible and personal notebook / journal', 'Willingness to observe holy silence throughout the weekend', 'Comfortable walking shoes for nature prayer trails']::text[], 6500, 'Includes 2 nights accommodation, all meals, and retreat materials', 'https://images.unsplash.com/photo-1479648230934-2ab6525f4847?auto=format&fit=crop&w=1200&q=80', 0, true),
  ('parish-leaders', 'Parish Pastoral Council & Ministry Leadership Retreat', 'group', 'Parish executive committees, choir leaders, Catholic Women & Men Association leaders', 'A transformative group retreat renewing the missionary spirit of church leaders. Combines deep scriptural reflection on servant leadership with practical strategic planning for deaneries.', '2026-10-23', '2026-10-25', 'Weekend Intensive (2 Nights)', array['Endorsement letter from Parish Priest or Deanery Dean', 'Parish strategic vision documents if available', 'Personal prayer book and Bible']::text[], 7500, 'Per participant (Full board accommodation + hall usage included)', 'https://images.unsplash.com/photo-1511632765486-a01980e01a18?auto=format&fit=crop&w=1200&q=80', 1, true),
  ('clergy', 'Annual Clergy Recollection & Spiritual Renewal', 'clergy', 'Priests, deacons, and religious serving in the Diocese of Ngong and beyond', 'Fraternal prayer, theological reflection, and Eucharistic renewal tailored for pastoral shepherds. Conducted in total quiet with daily concelebrated Mass and Liturgy of the Hours.', '2026-11-16', '2026-11-20', '5 Days (Monday – Friday)', array['Albs and diocesan stole for liturgical celebrations', 'Breviary (Christian Prayer) / Liturgy of the Hours']::text[], 14000, 'Comprehensive full board in self-contained suites', 'https://images.unsplash.com/photo-1499097505928-42fd92ac09f1?auto=format&fit=crop&w=1200&q=80', 2, true);
insert into public.formation_programs (slug, title, description, duration, schedule, requirements, fee_kes, fee_note, image_url, sort_order, is_published) values
  ('catechetics', 'Certificate in Catechetics & Pastoral Evangelization', 'Designed in accordance with the Diocese of Ngong pastoral plan to empower volunteer catechists and Sunday school instructors with sound biblical theology and pedagogies.', '4-Part Modular Seminar (Monthly Saturdays)', 'First Saturday of every month, 8:30 AM – 3:30 PM', array['Letter of recommendation from local parish priest', 'Basic literacy and active participation in parish life', 'Catechism of the Catholic Church (CCC)']::text[], 3000, 'Covers seminar binder, module handouts, and tea/lunch per session', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=1200&q=80', 0, true),
  ('family-life', 'Catholic Family Life & Marriage Enrichment Seminars', 'Guiding couples toward sacramental joy, open communication, Christian parenting, and financial stewardship according to Catholic social doctrine.', '2-Day Non-Residential or Residential Weekend', 'Quarterly Saturday & Sunday gatherings', array['Open to married couples and engaged couples in pre-cana preparation']::text[], 5000, 'Couple registration rate including seminar journals and refreshments', 'https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=1200&q=80', 1, true);
insert into public.events (slug, title, description, event_date, time_label, location, image_url, registration_open, sort_order) values
  ('allsaints-2026', '40th Anniversary Jubilee & Feast of All Saints', 'Commemorating 40 years of service since our founding on 1 November 1986. Solemn Pontifical High Mass, blessing of facilities, and thanksgiving celebration with all 44 parishes of Ngong Diocese.', '2026-11-01', '9:30 AM – 3:30 PM', 'Watakatifu Wote Grounds & St. Bernard Hall', 'https://images.unsplash.com/photo-1698822079732-501a7e06860f?auto=format&fit=crop&w=1200&q=80', true, 0),
  ('deanery-youth', 'Ngong Deanery Catholic Youth Formation Day', 'Bringing together youth leaders for fellowship, praise, catechesis on faith and career ethics, and spiritual coaching.', '2026-10-17', '8:00 AM – 4:30 PM', 'St. Julian Conference Hall & Outdoor Amphitheatre', 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1200&q=80', true, 1),
  ('past-laudato', 'Care for Creation & Ecology Symposium', 'In keeping with our core value "Integrity of Creation", environmental advocates and diocesan pastoral workers gathered to reflect on practical stewardship in Kajiado and Narok.', '2026-08-22', '9:00 AM – 4:00 PM', 'St. Bernard Hall', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1200&q=80', false, 2);
