insert into public.products (sku, name, category_id, description, price_kes, image_url, is_available, is_featured, sort_order) values
  ('BK-001', 'The African Bible (Paulines Publications)', (select id from public.product_categories where name = 'Religious Books'), 'Complete Catholic edition with extensive African context commentaries, liturgical references, study cross-references, and color maps.', 3800, 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=800&q=80', true, true, 0),
  ('BK-002', 'Catechism of the Catholic Church (Compact Edition)', (select id from public.product_categories where name = 'Religious Books'), 'Authoritative summary of Catholic faith and morals, essential for catechists, teachers, and family libraries.', 1500, 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=800&q=80', true, false, 1),
  ('PR-010', 'Misale Ya Kila Siku (Daily Swahili Missal)', (select id from public.product_categories where name = 'Prayer Materials'), 'Official Swahili translation containing the liturgical readings, psalms, and order of the Mass for all liturgical cycles.', 2200, 'https://images.unsplash.com/photo-1499652848871-1527a310b13a?auto=format&fit=crop&w=800&q=80', true, true, 2),
  ('DEV-004', 'Handcrafted Olive Wood Rosary with St. Benedict Crucifix', (select id from public.product_categories where name = 'Devotional Items'), 'Durable, cord-bound beads carved with care, featuring a silver-finish St. Benedict protection cross and centerpiece medal.', 850, 'https://images.unsplash.com/photo-1528357136257-0c25517acfea?auto=format&fit=crop&w=800&q=80', true, true, 3),
  ('DEV-008', 'Brown Scapular of Our Lady of Mount Carmel', (select id from public.product_categories where name = 'Devotional Items'), 'Authentic woven wool scapular with braided cords and accompanying enrollment blessing prayer leaflet.', 300, 'https://images.unsplash.com/photo-1569845177077-2a37322a60c7?auto=format&fit=crop&w=800&q=80', true, false, 4),
  ('GFT-015', 'Diocesan Beeswax Sanctuary Candles (Pack of 3)', (select id from public.product_categories where name = 'Gift Shop Items'), 'Clean-burning 100% natural beeswax candles crafted for home altars, prayer vigils, and chapel devotions.', 950, 'https://images.unsplash.com/photo-1603006905003-be475563bc59?auto=format&fit=crop&w=800&q=80', true, false, 5),
  ('GFT-022', 'Ngong Olivewood Wall Crucifix (10 inch)', (select id from public.product_categories where name = 'Gift Shop Items'), 'Solid carved hardwood cross with detailed corpus, suitable for homes, offices, and church sacristies.', 2400, 'https://images.unsplash.com/photo-1630892116465-8bb147daf88f?auto=format&fit=crop&w=800&q=80', true, true, 6),
  ('PR-014', 'Kitabu cha Njia Ya Msalaba (Stations of the Cross)', (select id from public.product_categories where name = 'Prayer Materials'), 'Standard prayer companion for Lenten devotions and personal Friday Stations of the Cross.', 250, 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=800&q=80', true, false, 7);
